const idx=`<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>PI PAY CI V16 PRO MAX - 1863 Pi - QR</title><script src="https://sdk.minepi.com/pi-sdk.js"></script><script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><style>body{font-family:Arial;background:#0f0f1a;color:white;text-align:center;padding:12px;margin:0}h1{margin:5px;font-size:22px;color:#00ff88}.card{background:#1a1a2e;border-radius:20px;padding:18px;margin:12px auto;max-width:480px;border:2px solid #7B2CBF;box-shadow:0 0 20px rgba(123,44,191,.3)}.btn{width:100%;padding:14px;border:none;border-radius:12px;font-size:15px;font-weight:bold;cursor:pointer;margin:6px 0}.open{background:#00ff88;color:#000}.close{background:#ff3344;color:#fff}.pay{background:#7B2CBF;color:#fff;font-size:17px}.cat{background:#2a2a4a;padding:12px;border-radius:12px;margin:10px 0;text-align:left;border-left:5px solid #00ff88}.service{display:inline-block;background:#3a3a6a;padding:8px 11px;border-radius:8px;margin:4px;cursor:pointer;font-size:12px;border:2px solid transparent;font-weight:600}.service.active{border-color:#00ff88;background:#00ff88;color:#000}.service-qr{background:#111;border-color:#facc15;color:#facc15}.service-qr.active{background:#facc15;color:#000}.tiroir{background:#2a2a4a;padding:10px;border-radius:12px;margin:8px 0;font-size:13px}input{width:92%;padding:11px;border-radius:10px;border:none;margin:6px 0;text-align:center;font-size:15px}.admin{background:#111;border:1px dashed #00ff88;border-radius:12px;padding:10px;margin:10px 0}.qrBox{background:#fff;padding:12px;border-radius:16px;margin:12px auto;max-width:320px;display:none}#qrcode{margin:10px auto;width:200px;height:200px;display:flex;justify-content:center;align-items:center}small{opacity:.7;font-size:11px}.grid-qr{display:flex;flex-wrap:wrap;justify-content:center;gap:6px}</style></head><body><h1>🔐 PI PAY CI V16 PRO MAX</h1><p style="color:#00ff88;font-size:11px;margin:2px">DG Abidjan - 1863 Pi - 01 Nov 2026 | Frais 0.25 Pi | QR Commercant PRO</p><div class="card"><div id="status">🔴 FERME</div><div class="tiroir">💰 Tiroir: 40 Pi + 10 Pi bonus = 50 Pi | Solde DG: <span id="solde">1863</span> Pi | Online: <span id="online">...</span></div><button class="btn open" onclick="ouvrir()">🟢 OUVRIR TIROIR - QR ACTIF</button><button class="btn close" onclick="fermer()">🔴 FERMER</button><div id="services" style="display:none"><div class="admin"><strong>⚙️ PANNEAU DG V16 PRO</strong><br><input id="tauxInput" type="number" value="1000" placeholder="Taux 1 Pi = FCFA"><br><input id="fraisInput" type="number" value="0.25" step="0.01" placeholder="Frais"><br><button onclick="changerConfig()" style="padding:7px 12px;border-radius:8px;border:none;background:#00ff88;font-weight:bold;cursor:pointer">Mettre a jour</button><p id="tauxAffiche" style="font-size:11px;color:#00ff88">Taux: 1 Pi = 1000 FCFA | Frais: 0.25 Pi</p></div><div class="cat"><strong>🏠 TA LISTE V14 - 13 BOUTONS PRO</strong><br><div class="grid-qr"><div class="service" onclick="choisir('SIDECI',event)">🏭 SIDECI</div><div class="service" onclick="choisir('CIE',event)">💡 CIE</div><div class="service" onclick="choisir('SOTRA',event)">🚌 SOTRA</div><div class="service" onclick="choisir('STAR',event)">📡 STAR</div><div class="service" onclick="choisir('LOYE',event)">🏠 LOYE</div><div class="service" onclick="choisir('ECOLE',event)">🎓 ECOLE</div><div class="service" onclick="choisir('MTN',event)">📱 MTN</div><div class="service" onclick="choisir('ORANGE',event)">🟠 ORANGE</div><div class="service" onclick="choisir('MOOV',event)">🔵 MOOV</div><div class="service" onclick="choisir('WAVE',event)">🌊 WAVE</div><div class="service" onclick="choisir('CANAL',event)">📺 CANAL</div><div class="service" onclick="choisir('USDT',event)">💲 USDT</div><div class="service" onclick="choisir('CARTE',event)">💳 CARTE</div></div></div><div class="cat" style="border-left-color:#facc15"><strong>📱 QR BOUTIQUES - MAGAZINES - MARQUES</strong><br><div class="grid-qr"><div class="service service-qr" onclick="choisir('QR BOUTIQUE',event)">📱 QR BOUTIQUE</div><div class="service service-qr" onclick="choisir('QR MAGAZINE',event)">📚 MAGAZINE</div><div class="service service-qr" onclick="choisir('MARQUES',event)">🏷️ MARQUES</div><div class="service service-qr" onclick="choisir('APPEL',event)">📞 APPEL</div><div class="service service-qr" onclick="choisir('INTERNET',event)">🌐 INTERNET</div></div></div><input id="num" placeholder="Numero client / Boutique"><input id="fcfa" type="number" placeholder="Montant FCFA (ex: 5000)" oninput="calculer()"><p id="calc" style="color:#00ff88;font-weight:bold;font-size:13px"></p><div id="qrZone" class="qrBox"><p style="color:#000;font-weight:bold;margin:4px">📱 QR CODE POUR LE CLIENT :</p><div id="qrcode"></div><p id="qrDataText" style="color:#333;font-size:10px;word-break:break-all"></p><p style="font-size:10px;color:#666">Client scanne ce QR pour payer avec Pi Browser</p></div></div><button class="btn pay" id="payBtn" onclick="payer()" style="display:none">💳 PAYER + GENERER QR</button><p id="log" style="font-size:11px;min-height:20px"></p></div><small>V16 PRO MAX - DG ABIDJAN - Pi Pay CI - 1863 Pi - QR Commercant</small><script>
let CONFIG_PI_PAY={taux_pi_fcfa:1000,frais_fixe_pi:0.25,version:"V16 PRO MAX QR"};try{Pi.init({version:"2.0",sandbox:true});}catch(e){console.log(e)}
let ouvert=false,serviceChoisi="",piAPayer=0,pi_base=0,frais=0;let qrCodeObj=null;
function updateOnline(){document.getElementById('online').textContent=navigator.onLine?'🟢 ON':'🔴 OFF';document.getElementById('online').style.color=navigator.onLine?'#00ff88':'#ff3344'}setInterval(updateOnline,2000);updateOnline();
function changerConfig(){let nt=parseFloat(document.getElementById('tauxInput').value),nf=parseFloat(document.getElementById('fraisInput').value);if(nt>0)CONFIG_PI_PAY.taux_pi_fcfa=nt;if(nf>=0)CONFIG_PI_PAY.frais_fixe_pi=nf;document.getElementById('tauxAffiche').innerText="Taux: 1 Pi = "+CONFIG_PI_PAY.taux_pi_fcfa+" FCFA | Frais: "+CONFIG_PI_PAY.frais_fixe_pi+" Pi";calculer()}
function calculer(){let fcfa=parseFloat(document.getElementById('fcfa').value);if(fcfa&&CONFIG_PI_PAY.taux_pi_fcfa){pi_base=fcfa/CONFIG_PI_PAY.taux_pi_fcfa;frais=pi_base*CONFIG_PI_PAY.frais_fixe_pi;piAPayer=pi_base+frais;document.getElementById('calc').innerText=pi_base.toFixed(2)+" Pi + "+frais.toFixed(2)+" Pi frais = "+piAPayer.toFixed(2)+" Pi TOTAL";document.getElementById('payBtn').innerText="💳 PAYER "+piAPayer.toFixed(2)+" Pi - "+serviceChoisi;genererQRCommercant(fcfa,piAPayer)}}
function genererQRCommercant(fcfa,piTotal){document.getElementById('qrZone').style.display="block";let qrDiv=document.getElementById('qrcode');qrDiv.innerHTML="";let data="PI-PAY-CI-V16|DG:ABIDJAN-1863Pi|Service:"+serviceChoisi+"|FCFA:"+fcfa+"|Pi:"+piTotal.toFixed(4)+"|Taux:"+CONFIG_PI_PAY.taux_pi_fcfa+"|Boutique:San-Pedro|QR:"+Date.now();document.getElementById('qrDataText').innerText=data;qrCodeObj=new QRCode(qrDiv,{text:data,width:180,height:180,colorDark:"#000",colorLight:"#fff",correctLevel:QRCode.CorrectLevel.H});}
function ouvrir(){ouvert=true;document.getElementById('status').innerHTML="🟢 OUVERT - QR ACTIF - 13 SERVICES";document.getElementById('services').style.display="block";document.getElementById('payBtn').style.display="block";document.getElementById('log').innerText="✅ Tiroir ouvert - V16 PRO MAX - Pret pour QR";}function fermer(){ouvert=false;document.getElementById('status').innerHTML="🔴 FERME";document.getElementById('services').style.display="none";document.getElementById('payBtn').style.display="none";document.getElementById('qrZone').style.display="none";document.getElementById('log').innerText="🔒 Ferme";}
function choisir(s,evt){serviceChoisi=s;document.querySelectorAll('.service').forEach(e=>e.classList.remove('active'));evt.target.classList.add('active');document.getElementById('log').innerText="✅ "+s+" choisi - Entre FCFA";calculer();}
async function payer(){if(!ouvert){alert("Ouvre VERT !");return}if(!serviceChoisi){alert("Choisis service !");return}const num=document.getElementById('num').value,fcfa=document.getElementById('fcfa').value;if(!num||!fcfa){alert("Numero + FCFA !");return}try{if(typeof Pi==='undefined'){alert("Ouvre dans Pi Browser !");return}const authScopes=['username','payments'];function onInc(p){return fetch('/api/pi/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paymentId:p.identifier})})}await Pi.authenticate(authScopes,onInc);await Pi.createPayment({amount:piAPayer,memo:"PI PAY CI V16 PRO MAX - "+serviceChoisi+" "+fcfa+" FCFA - QR "+num,metadata:{service:serviceChoisi,fcfa:fcfa,pi_base:pi_base,frais:frais,qr:true,v:"16",dg:"1863"}},{onReadyForServerApproval:(id)=>{document.getElementById('log').innerText="⏳ Paiement QR "+id+" - Montre le QR au client "+serviceChoisi},onReadyForServerCompletion:(id,tx)=>{document.getElementById('log').innerText="✅ Paye QR "+piAPayer.toFixed(2)+" Pi TX:"+tx+" - "+serviceChoisi+" OK";document.getElementById('solde').innerText=(1863-piAPayer).toFixed(2)},onCancel:()=>{document.getElementById('log').innerText="❌ Annule"},onError:(e)=>{document.getElementById('log').innerText="Erreur "+e.message}});}catch(e){document.getElementById('log').innerText="❌ "+(e.message||e)}};
</script></body></html>`
